roadprobe=r'''window.__roadBase=s=>{__townTest.load(s);const original=regionalGateway,gates=Object.fromEntries(OUTSIDE_MARKETS.map(m=>[m.id,original(m)])),cut=[...new Set(Object.values(gates))];regionalGateway=m=>gates[m.id];for(const id of cut)G.tiles[id]=0;invalidateRoads(false);for(let d=1;d<=240;d++){if(d===121){for(const id of cut)G.tiles[id]=1;invalidateRoads(false);}__townTest.step(1);}regionalGateway=original;return __townTest.save()};'''
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.set_default_timeout(180000);errs=[];p.on('pageerror',lambda e:errs.append(str(e)));p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n'+roadprobe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click()
